def largest_remainder(total, weights):
    if total < 0 or any(w < 0 for w in weights):
        raise ValueError("negative")
    s=sum(weights)
    if total == 0:
        return [0 for _ in weights]
    if s == 0:
        raise ValueError("zero")
    numerators=[total*w for w in weights]
    result=[n//s for n in numerators]
    remaining=total-sum(result)
    order=sorted(range(len(weights)), key=lambda i: (-(numerators[i] % s), i))
    for i in order[:remaining]:
        result[i]+=1
    return result

sources.dedupe-events:
def dedupe_events(events):
    chosen={}
    for index,event in enumerate(events):
        key=event["id"]
        current=chosen.get(key)
        if current is None or event["seq"] >= current[1]["seq"]:
            chosen[key]=(index, dict(event))
    selected=list(chosen.values())
    selected.sort(key=lambda pair:(pair[1]["seq"], pair[0]))
    return [event for _,event in selected]

