def quorum_decision(votes, quorum):
    if quorum <= 0 or any(v not in ("yes","no","abstain") for v in votes):
        raise ValueError("invalid")
    yes=votes.count("yes"); no=votes.count("no")
    if yes+no < quorum:
        return "no-quorum"
    if yes > no: return "yes"
    if no > yes: return "no"
    return "tie"

sources.chunk-windows:
def chunk_windows(items, size, overlap):
    if size <= 0 or overlap < 0 or overlap >= size:
        raise ValueError("invalid")
    if not items:
        return []
    step=size-overlap
    return [list(items[i:i+size]) for i in range(0,len(items),step)]

sources.select-latest:
def select_latest(records):
    chosen={}
    for index,record in enumerate(records):
        if record["revision"] < 0 or record["observed"] < 0:
            raise ValueError("negative")
        key=record["key"]; current=chosen.get(key)
        rank=(record["revision"],record["observed"],index)
        if current is None or rank > current[0]:
            chosen[key]=(rank,dict(record))
    return [chosen[key][1] for key in sorted(chosen)]

