def normalize_tags(tags):
    out=[]; seen=set()
    for tag in tags:
        if not isinstance(tag,str):
            raise ValueError("type")
        value=tag.strip()
        if not value:
            raise ValueError("empty")
        key=value.casefold()
        if key not in seen:
            seen.add(key); out.append(value)
    return out
